import type { ReactNode } from 'react';
import { articles, type Article } from '../lib/content';
import { Icon, CodeBlock, SourceRefs } from './ui';
const href=(a:Article)=>a.slug?`/docs/${a.slug}/`:'/docs/';
export function ArticleBody({article}:{article:Article}){return <>{article.sections.map(s=><section className="doc-section" key={s.id}><h2 id={s.id}><a href={`#${s.id}`}>{s.title}<span aria-hidden="true" className="anchor-mark">#</span></a></h2>{s.paragraphs.map(p=><p key={p}>{p}</p>)}{s.bullets&&<ul>{s.bullets.map(b=><li key={b}>{b}</li>)}</ul>}{s.code&&<CodeBlock code={s.code} note={s.note}/>}</section>)}</>}
function Topics({current}:{current:string}){return <nav aria-label="Documentation topics">{['Start here','Systems','Principles'].map(group=><div className="topic-group" key={group}><p>{group}</p>{articles.filter(a=>a.group===group).map(a=><a key={a.slug} href={href(a)} aria-current={a.slug===current?'page':undefined}>{a.title}</a>)}</div>)}</nav>}
export function DocsPage({article,body}:{article:Article;body?:ReactNode}){
 const index=articles.findIndex(a=>a.slug===article.slug),prev=articles[index-1],next=articles[index+1];
 return <div className="container docs-layout"><aside className="docs-sidebar"><a className="docs-brand" href="/docs/"><Icon name="book"/>Field guide</a><button type="button" className="docs-search-button" data-open-search=""><Icon name="search"/>Search docs<kbd>⌘ K</kbd></button><Topics current={article.slug}/><a className="docs-source-link" href="https://github.com/donaldfilimon/MLAI-CORPORATION-WWW" target="_blank" rel="noopener noreferrer">Explore the repository<Icon name="external"/></a></aside><div className="docs-center"><details className="mobile-topics"><summary><Icon name="menu"/>Documentation topics<Icon name="chevron"/></summary><Topics current={article.slug}/><button type="button" className="docs-search-button" data-open-search=""><Icon name="search"/>Search documentation</button></details><div className="breadcrumbs"><a href="/docs/">Documentation</a><Icon name="chevron"/><span>{article.slug?article.title:'Overview'}</span></div><article className="docs-article"><header className="doc-header"><h1>{article.title}</h1><p>{article.description}</p><div className="doc-utilities"><span>{article.group}</span><button type="button" data-copy-page=""><Icon name="copy"/>Copy page text</button></div><p className="page-copy-status" role="status"></p></header><div id="article-content">{body||<ArticleBody article={article}/>}</div><SourceRefs ids={article.sources}/></article><nav className="doc-pagination" aria-label="Adjacent documentation">{prev?<a href={href(prev)}><small>Previous guide</small><strong>{prev.title}</strong></a>:<span/>}{next?<a href={href(next)}><small>Next guide<Icon name="arrow"/></small><strong>{next.title}</strong></a>:<a href="/projects/"><small>Explore next<Icon name="arrow"/></small><strong>Project directory</strong></a>}</nav></div><aside className="docs-toc"><p>ON THIS PAGE</p><nav aria-label="On this page">{article.sections.map(s=><a key={s.id} href={`#${s.id}`}>{s.title}</a>)}</nav><div className="toc-note"><Icon name="layers"/><span>A field guide, not a live runtime. Start with the source.</span></div></aside></div>;
}
